<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/economy.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice=(string)($_SESSION['dn_item_notice']??'');unset($_SESSION['dn_item_notice']);$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
    pv_require_csrf();$action=(string)($_POST['action']??'');$token=(string)($_POST['request_token']??'');$item=(int)($_POST['item_id']??0);
    if($action==='buy')$notice=dn_buy_item($db,$uid,$item,(int)($_POST['qty']??1),$token);
    elseif($action==='use')$notice=dn_use_recovery_item($db,$uid,$item,(int)($_POST['digimon_id']??0),$token);
    else throw new RuntimeException('Unknown item action.');
    $_SESSION['dn_item_notice']=$notice;pv_redirect('items.php');
}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'The item request failed safely.';pv_log('Items: '.$e->getMessage());}
$items=dn_inventory($db,$uid);$collection=dn_collection_rows($db,$uid);$wallet=(int)(dn_row($db,'SELECT money FROM members WHERE id=?',[$uid])['money']??0);$battle=dn_active_battle($db,$uid);$busy=$battle&&empty($battle['finished']);pv_page_start('Supply shop','items.php',true);
?>
<div class="pv-game-layout"><?php pv_game_side_menu('items.php');?><main class="pv-main-column"><section class="pv-page"><section class="nxt-shop-welcome"><div class="nxt-merchant"><img src="<?=pv_h(pv_asset('ui/shopkeeper.png'))?>" width="176" height="176" alt="The hooded Digimon NXT shopkeeper"></div><div><span class="pv-eyebrow">DIGIMON NXT / SUPPLY TERMINAL</span><h1>A little backup.<br>A lot more adventure.</h1><p class="pv-subtle">Welcome, tamer. Keep your partners ready with HP and SP capsules, then get back out there.</p><span class="nxt-shop-note">RECOVERY SUPPLIES · SMALL / MEDIUM / LARGE</span></div><div class="pv-wallet"><span>YOUR BITS</span><strong><?=number_format($wallet)?></strong><small>Ready for your next run</small></div></section>
<?php if($notice):?><div class="pv-flash success" role="status"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error" role="alert"><?=pv_h($error)?></div><?php endif;?>
<?php if($busy):?><div class="pv-flash">A wild battle is in progress. <a href="<?=pv_h(pv_url('wildbattle.php'))?>">Return to battle to use capsules.</a></div><?php endif;?>
<div class="pv-shop-grid"><?php foreach($items as $it):$effect=dn_recovery_catalog()[$it['slug']]??null;if(!$effect)continue;$max=min(99,(int)$it['stack_limit']-(int)$it['quantity'],intdiv($wallet,max(1,(int)$it['price'])));?><article class="pv-shop-card">
<div class="pv-shop-art dn-capsule-art <?=pv_h($effect['field'])?>"><b class="dn-capsule-shape size-<?=pv_h(substr($it['slug'],-1))?>" aria-hidden="true"><i></i><em>+</em></b><span><?=strtoupper($effect['field'])?> · <?=strtoupper(substr($it['slug'],-1))?></span></div><div class="pv-shop-copy"><small>RESTORE <?=(int)$effect['amount']?> <?=strtoupper($effect['field'])?></small><h3><?=pv_h($it['name'])?></h3><p><?=pv_h($it['description'])?></p><strong><?=number_format((int)$it['price'])?> Bits each</strong><p>Owned <?=(int)$it['quantity']?> / <?=(int)$it['stack_limit']?></p></div>
<form method="post" class="pv-shop-buy"><?=pv_csrf_field()?><input type="hidden" name="request_token" value="<?=bin2hex(random_bytes(24))?>"><input type="hidden" name="action" value="buy"><input type="hidden" name="item_id" value="<?=(int)$it['id']?>"><label>Quantity<input type="number" name="qty" min="1" max="<?=max(1,$max)?>" value="1" <?=$max<1?'disabled':''?>></label><button class="pv-button pv-button-secondary" <?=$max<1?'disabled':''?>>Buy</button></form>
<?php $eligible=array_filter($collection,fn($d)=>(int)$d['hp']>0&&!(int)$d['locked_trade']&&(int)$d[$effect['field']]<(int)$d['max_'.$effect['field']]);if((int)$it['quantity']>0&&$collection):?><form method="post" class="dn-capsule-use"><?=pv_csrf_field()?><input type="hidden" name="request_token" value="<?=bin2hex(random_bytes(24))?>"><input type="hidden" name="action" value="use"><input type="hidden" name="item_id" value="<?=(int)$it['id']?>"><label>Heal Digimon<select name="digimon_id"><?php foreach($collection as $d):$valid=(int)$d['hp']>0&&!(int)$d['locked_trade']&&(int)$d[$effect['field']]<(int)$d['max_'.$effect['field']];?><option value="<?=(int)$d['id']?>" <?=$valid?'':'disabled'?>><?=pv_h($d['nickname']?:$d['name'])?> · <?=strtoupper($effect['field'])?> <?=(int)$d[$effect['field']]?>/<?=(int)$d['max_'.$effect['field']]?></option><?php endforeach;?></select></label><button class="pv-button" <?=$busy||!$eligible?'disabled':''?>>Use capsule</button></form><?php endif;?></article><?php endforeach;?></div>
<p class="pv-subtle">Defeated Digimon need the Recovery Terminal or a revival skill. Full vitals and invalid targets never consume a capsule.</p></section></main></div><?php pv_page_end();?>
